-- Frozen 2026-11-18 DB-only cohort for #45475, following pilot #48331.
-- All 6,589 orgs had no retained workspace Run in 30 days. No Clerk or Guide writes.
-- Recheck identities, membership, inactivity and canonical source data at execution.
-- Changed/ineligible orgs are skipped without replacement; this journal will not
-- retry them later. Keep source Agents/Workflows and immutable R2 packages intact.
-- Reuse the deployed #46786 readers and the staff/pilot copy and event contracts.
-- Keep the runner's 1s lock/10s statement limits and atomic migration/journal commit.
SET LOCAL TIME ZONE 'UTC';
--> statement-breakpoint
CREATE FUNCTION pg_temp.inactive_batch_uuid(value text) RETURNS uuid
LANGUAGE sql IMMUTABLE STRICT AS $fn$
  SELECT overlay(overlay(md5(value) placing '5' from 13 for 1) placing '8' from 17 for 1)::uuid
$fn$;
--> statement-breakpoint
CREATE TEMP TABLE inactive_batch_cohort (
  org_id text PRIMARY KEY, default_agent_id uuid NOT NULL,
  members text[] NOT NULL, cached_members text[] NOT NULL,
  agents uuid[] NOT NULL, workflows uuid[] NOT NULL,
  automations uuid[] NOT NULL, chats uuid[] NOT NULL
) ON COMMIT DROP;
INSERT INTO inactive_batch_cohort
-- Compact rows: org, default executor, initialized members, additional cached
-- members, non-default Agents, all Workflows, all Automations, legacy Chats.
SELECT value->>0,(value->>1)::uuid,
  ARRAY(SELECT jsonb_array_elements_text(value->2)),
  ARRAY(SELECT jsonb_array_elements_text(value->2) UNION SELECT jsonb_array_elements_text(value->3) ORDER BY 1),
  ARRAY(SELECT (value->>1)::uuid UNION SELECT jsonb_array_elements_text(value->4)::uuid ORDER BY 1),
  ARRAY(SELECT jsonb_array_elements_text(value->5)::uuid),
  ARRAY(SELECT jsonb_array_elements_text(value->6)::uuid),
  ARRAY(SELECT jsonb_array_elements_text(value->7)::uuid)
FROM jsonb_array_elements($cohort$
