-- Only the frozen, initialized old members activate. Preserve unrelated keys.
UPDATE user_feature_switches f SET switches=f.switches || '{"singleAgent":true}'::jsonb,updated_at=now()
FROM inactive_copy_target t WHERE f.org_id=t.org_id AND f.user_id=ANY(t.members);
